<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Bar do Primo | Estoque</title><style>
:root{--verde:#075740;--verde2:#108a48;--amarelo:#f4bd18;--claro:#f4fbf5;--texto:#17352d}*{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;background:var(--claro);color:var(--texto)}.top{background:var(--verde);color:#fff;padding:16px 5%;display:flex;align-items:center;justify-content:space-between}.brand{font-size:22px;font-weight:800}.brand span{color:#ffe171}.top small{opacity:.8}.nav{background:#fff;padding:10px 5%;display:flex;gap:8px;box-shadow:0 2px 10px #003b2320}.nav a,.btn{padding:10px 14px;border-radius:9px;text-decoration:none;border:0;font-weight:700;cursor:pointer}.nav a{color:var(--verde)}.nav a:hover,.nav a.active{background:#e5f5e9}.wrap{max-width:1200px;margin:28px auto;padding:0 20px}.hero{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.hero h1{margin:0;font-size:28px}.btn{background:var(--verde2);color:#fff;display:inline-block}.btn.yellow{background:var(--amarelo);color:#17352d}.btn.danger{background:#b73535}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card{background:#fff;border:1px solid #d9ebdc;border-radius:15px;padding:19px;box-shadow:0 4px 14px #064b2d0c}.number{font-size:31px;font-weight:800;color:var(--verde)}.label{font-size:13px;color:#5b746b;text-transform:uppercase;font-weight:bold}table{width:100%;border-collapse:collapse;background:#fff;border-radius:14px;overflow:hidden}th,td{padding:13px;text-align:left;border-bottom:1px solid #e8f0e9}th{background:#e7f5e9;color:var(--verde);font-size:12px;text-transform:uppercase}.badge{padding:5px 9px;border-radius:20px;font-size:12px;font-weight:bold}.ok{background:#d8f4df;color:#18703a}.alert{background:#fff0ca;color:#8a5e00}.in{color:#168042;font-weight:bold}.out{color:#b73535;font-weight:bold}.flash{padding:13px;border-radius:10px;margin-bottom:18px;background:#d8f4df;color:#166534}.error{background:#fee2e2;color:#991b1b}.form{background:#fff;padding:24px;border-radius:15px;border:1px solid #d9ebdc;display:grid;grid-template-columns:repeat(2,1fr);gap:16px}.form .full{grid-column:1/-1}label{display:block;font-size:13px;font-weight:bold;margin-bottom:6px;color:#31584a}input,select,textarea{width:100%;padding:11px;border:1px solid #cfe0d2;border-radius:8px;font:inherit}textarea{min-height:85px}.actions{display:flex;gap:8px;align-items:center}.muted{color:#698079;font-size:14px}.login{min-height:100vh;display:grid;place-items:center;background:linear-gradient(135deg,#064c3a,#078545)}.login .box{background:white;border-radius:20px;padding:36px;width:min(420px,92vw);text-align:center}.login h1{color:var(--verde);margin:5px}.login form{text-align:left;margin-top:25px}.login button{width:100%;margin-top:12px}.right{display:flex;gap:10px;align-items:center}.inline{display:inline}.empty{padding:25px;text-align:center;background:#fff;border-radius:12px}@media(max-width:720px){.grid,.form{grid-template-columns:1fr}.nav{overflow:auto}.top small{display:none}.wrap{padding:0 12px}.hero{align-items:flex-start;gap:12px}.hero h1{font-size:22px}table{font-size:13px}}
